create table if not exists public.game_votes(id uuid primary key default gen_random_uuid(),game_id text not null,voter_id uuid not null references auth.users(id) on delete cascade,created_at timestamptz not null default now(),constraint game_votes_game_voter_unique unique(game_id,voter_id));create index if not exists game_votes_game_id_idx on public.game_votes(game_id);create index if not exists game_votes_created_at_idx on public.game_votes(created_at desc);alter table public.game_votes enable row level security;revoke all on table public.game_votes from anon,authenticated;grant insert on table public.game_votes to authenticated;create policy "Users can insert their own game votes" on public.game_votes for insert to authenticated with check((select auth.uid())=voter_id);
create or replace function public.tecnomath_get_vote_counts() returns table(game_id text,votes bigint) language sql security definer set search_path='' stable as $$ select gv.game_id,count(*)::bigint from public.game_votes gv group by gv.game_id; $$;revoke execute on function public.tecnomath_get_vote_counts() from public;grant execute on function public.tecnomath_get_vote_counts() to anon,authenticated;
create or replace function public.tecnomath_get_my_votes() returns table(game_id text) language sql security definer set search_path='' stable as $$ select gv.game_id from public.game_votes gv where gv.voter_id=(select auth.uid()); $$;revoke execute on function public.tecnomath_get_my_votes() from public;grant execute on function public.tecnomath_get_my_votes() to authenticated;
create or replace function public.tecnomath_broadcast_game_vote() returns trigger language plpgsql security definer set search_path='' as $$ begin perform realtime.send(jsonb_build_object('game_id',NEW.game_id,'created_at',NEW.created_at),'VOTE','tecnomath-voting',true);return NEW;end; $$;revoke execute on function public.tecnomath_broadcast_game_vote() from public,anon,authenticated;drop trigger if exists game_votes_realtime_broadcast on public.game_votes;create trigger game_votes_realtime_broadcast after insert on public.game_votes for each row execute function public.tecnomath_broadcast_game_vote();
drop policy if exists "Authenticated users can receive voting broadcasts" on realtime.messages;create policy "Authenticated users can receive voting broadcasts" on realtime.messages for select to authenticated using((select realtime.topic())='tecnomath-voting');